<?php
require_once __DIR__ . '/includes/auth.php';
require_once __DIR__ . '/includes/csdl_store.php';
require_once __DIR__ . '/includes/noitru_assignment_store.php';
require_login();
require_module('thidua', 'view');

$user=current_user()??[];$userName=trim((string)($user['name']??$user['teacher_name']??$user['username']??''));
$permissions=['input'=>'td.student_room_input','stats'=>'td.student_room_stats','settings'=>'td.student_room_settings'];
$allowedTabs=[];foreach($permissions as $key=>$code)if(can_perm_level($code,'view'))$allowedTabs[]=$key;
if(!$allowedTabs){http_response_code(403);exit('Tài khoản chưa được cấp quyền cho Phòng nội trú.');}
$tab=(string)($_GET['tab']??$allowedTabs[0]);if(!in_array($tab,$allowedTabs,true)){http_response_code(403);exit('Tài khoản chưa được cấp quyền cho tab này.');}
$canEdit=can_perm_level($permissions[$tab],'edit');$canDelete=can_perm_level($permissions[$tab],'delete');

$dataFile=DATA_PATH.'/thidua_rooms.json';
$data=load_json($dataFile,[]);$data=array_merge(['settings'=>[],'criteria'=>[],'entries'=>[]],is_array($data)?$data:[]);
$data['settings']=array_merge(['weekly_max'=>100,'excellent'=>90,'good'=>80,'pass'=>65],is_array($data['settings']??null)?$data['settings']:[]);
$data['criteria']=array_values(is_array($data['criteria']??null)?$data['criteria']:[]);$data['entries']=array_values(is_array($data['entries']??null)?$data['entries']:[]);
if(!$data['criteria'])$data['criteria']=[
 ['id'=>'rc_clean','name'=>'Vệ sinh phòng bẩn','points'=>5,'active'=>true],
 ['id'=>'rc_bed','name'=>'Chăn, màn, đồ dùng sắp xếp chưa gọn','points'=>3,'active'=>true],
 ['id'=>'rc_discipline','name'=>'Vi phạm giờ giấc, nội quy phòng ở','points'=>5,'active'=>true],
];

$assignment=noitru_assignments_data();$rooms=array_values(array_unique(array_filter(array_map('strval',(array)($assignment['room_names']??[])))));
foreach((array)($assignment['rooms']??[]) as $room){$room=trim((string)$room);if($room!==''&&!in_array($room,$rooms,true))$rooms[]=$room;}
sort($rooms,SORT_NATURAL|SORT_FLAG_CASE);

function td_room_redirect(string $tab,array $extra=[]): void {$query=http_build_query(['tab'=>$tab]+$extra);header('Location: '.BASE_URL.'thidua_phongnoitru.php?'.$query);exit;}
function td_room_week(string $date): array {$shared=csdl_week_for_date($date);if($shared)return $shared;$time=strtotime($date)?:time();$start=date('Y-m-d',strtotime('monday this week',$time));return ['start'=>$start,'end'=>date('Y-m-d',strtotime($start.' +6 days')),'label'=>date('d/m',strtotime($start)).' - '.date('d/m/Y',strtotime($start.' +6 days'))];}
function td_room_rating(float $score,float $max,array $settings): string {$percent=$max>0?$score*100/$max:0;if($percent>=(float)$settings['excellent'])return 'Tốt';if($percent>=(float)$settings['good'])return 'Khá';if($percent>=(float)$settings['pass'])return 'Đạt';return 'Chưa đạt';}
function td_room_entry_key(array $entry): string {return (string)($entry['week_start']??'').'|'.(string)($entry['room']??'');}

if(empty($_SESSION['td_room_csrf']))$_SESSION['td_room_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['td_room_csrf'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Phiên làm việc không hợp lệ.');}
 $action=(string)($_POST['action']??'');$actionTab=['entry_save'=>'input','entry_delete'=>'input','settings_save'=>'settings'][$action]??'';
 if($actionTab===''||!in_array($actionTab,$allowedTabs,true)){http_response_code(403);exit('Không có quyền thực hiện thao tác này.');}
 $needed=$action==='entry_delete'?'delete':'edit';if(!can_perm_level($permissions[$actionTab],$needed)){http_response_code(403);exit('Tài khoản chưa có quyền '.$needed.' tại tab này.');}
 if($action==='settings_save'){
   $weeklyMax=max(1,(float)($_POST['weekly_max']??100));$excellent=max(0,min(100,(float)($_POST['excellent']??90)));$good=max(0,min($excellent,(float)($_POST['good']??80)));$pass=max(0,min($good,(float)($_POST['pass']??65)));
   $ids=(array)($_POST['criterion_id']??[]);$names=(array)($_POST['criterion_name']??[]);$points=(array)($_POST['criterion_points']??[]);$active=(array)($_POST['criterion_active']??[]);$criteria=[];
   foreach($names as $index=>$name){$name=trim((string)$name);if($name==='')continue;$id=preg_replace('/[^a-zA-Z0-9_-]/','',(string)($ids[$index]??''));if($id==='')$id='rc_'.bin2hex(random_bytes(5));$criteria[]=['id'=>$id,'name'=>$name,'points'=>max(.01,(float)($points[$index]??1)),'active'=>(string)($active[$index]??'1')==='1'];}
   if(!$criteria){flash('Cần ít nhất một mục điểm trừ.','danger');td_room_redirect('settings');}
   $data['settings']=['weekly_max'=>$weeklyMax,'excellent'=>$excellent,'good'=>$good,'pass'=>$pass];$data['criteria']=$criteria;save_json($dataFile,$data);flash('Đã lưu tổng điểm, ngưỡng xếp loại và các mục điểm trừ.','success');td_room_redirect('settings');
 }
 if($action==='entry_save'){
   $room=trim((string)($_POST['room']??''));if(!in_array($room,$rooms,true)){flash('Phòng ở không có trong danh sách nội trú.','danger');td_room_redirect('input');}
   $date=trim((string)($_POST['date']??date('Y-m-d')));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$date=date('Y-m-d');$week=td_room_week($date);
   $criterionMap=[];foreach($data['criteria'] as $criterion)if(!empty($criterion['active']))$criterionMap[(string)$criterion['id']]=$criterion;
   $selected=(array)($_POST['criterion']??[]);$quantities=(array)($_POST['quantity']??[]);$notes=(array)($_POST['item_note']??[]);$aggregated=[];
   foreach($selected as $index=>$criterionId){$criterionId=(string)$criterionId;if(!isset($criterionMap[$criterionId]))continue;$qty=max(1,(int)($quantities[$index]??1));if(!isset($aggregated[$criterionId]))$aggregated[$criterionId]=['criterion_id'=>$criterionId,'name'=>(string)$criterionMap[$criterionId]['name'],'points'=>(float)$criterionMap[$criterionId]['points'],'quantity'=>0,'note'=>''];$aggregated[$criterionId]['quantity']+=$qty;$note=trim((string)($notes[$index]??''));if($note!=='')$aggregated[$criterionId]['note']=trim($aggregated[$criterionId]['note'].'; '.$note,'; ');}
   $items=array_values($aggregated);$deduction=0;foreach($items as $item)$deduction+=(float)$item['points']*(int)$item['quantity'];$max=(float)$data['settings']['weekly_max'];$score=max(0,$max-$deduction);
   $row=['id'=>'tre_'.bin2hex(random_bytes(7)),'room'=>$room,'date'=>$date,'week_start'=>$week['start'],'week_end'=>$week['end'],'week_label'=>$week['label']??'','items'=>$items,'deduction'=>round($deduction,2),'max_score'=>$max,'score'=>round($score,2),'rating'=>td_room_rating($score,$max,$data['settings']),'general_note'=>trim((string)($_POST['general_note']??'')),'created_by'=>$userName,'created_at'=>date('c'),'updated_by'=>$userName,'updated_at'=>date('c')];
   $found=false;foreach($data['entries'] as &$entry)if(td_room_entry_key($entry)===$week['start'].'|'.$room){$row['id']=$entry['id']??$row['id'];$row['created_by']=$entry['created_by']??$userName;$row['created_at']=$entry['created_at']??date('c');$entry=$row;$found=true;break;}unset($entry);if(!$found)$data['entries'][]=$row;
   save_json($dataFile,$data);flash(($found?'Đã cập nhật':'Đã lưu').' điểm phòng '.$room.'; còn '.$score.'/'.$max.' điểm.','success');td_room_redirect('input',['week'=>$week['start']]);
 }
 if($action==='entry_delete'){$id=trim((string)($_POST['id']??''));$before=count($data['entries']);$data['entries']=array_values(array_filter($data['entries'],fn($row)=>(string)($row['id']??'')!==$id));if(count($data['entries'])===$before){flash('Không tìm thấy dữ liệu cần xóa.','warning');}else{save_json($dataFile,$data);flash('Đã xóa dữ liệu chấm điểm phòng.','warning');}td_room_redirect('input',['week'=>(string)($_POST['week']??'')]);}
}

$weekRequest=(string)($_GET['week']??date('Y-m-d'));$inputWeek=td_room_week($weekRequest);$inputMap=[];foreach($data['entries'] as $entry)if(($entry['week_start']??'')===$inputWeek['start'])$inputMap[(string)($entry['room']??'')]=$entry;
$statsMode=($_GET['mode']??'week')==='range'?'range':'week';$statsAnchor=(string)($_GET['anchor']??date('Y-m-d'));$statsWeek=td_room_week($statsAnchor);$from=$statsMode==='week'?$statsWeek['start']:(string)($_GET['from']??date('Y-m-01'));$to=$statsMode==='week'?$statsWeek['end']:(string)($_GET['to']??date('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$to<$from)$to=$from;
$summary=[];foreach($rooms as $room)$summary[$room]=['room'=>$room,'weeks'=>0,'total'=>0.0,'average'=>0.0,'deduction'=>0.0,'latest_rating'=>'','details'=>[]];foreach($data['entries'] as $entry){$date=(string)($entry['date']??$entry['week_start']??'');$room=(string)($entry['room']??'');if($date<$from||$date>$to||!isset($summary[$room]))continue;$summary[$room]['weeks']++;$summary[$room]['total']+=(float)($entry['score']??0);$summary[$room]['deduction']+=(float)($entry['deduction']??0);$summary[$room]['latest_rating']=(string)($entry['rating']??'');$summary[$room]['details'][]=$entry;}foreach($summary as &$row)if($row['weeks']){$row['average']=round($row['total']/$row['weeks'],2);$row['rating']=td_room_rating($row['average'],(float)$data['settings']['weekly_max'],$data['settings']);}unset($row);uasort($summary,function($a,$b){if(!$a['weeks']&&!$b['weeks'])return strnatcasecmp($a['room'],$b['room']);if(!$a['weeks'])return 1;if(!$b['weeks'])return -1;return ($b['average']<=>$a['average'])?:strnatcasecmp($a['room'],$b['room']);});
$activeCriteria=array_values(array_filter($data['criteria'],fn($row)=>!empty($row['active'])));
?>
