</style></head><body><div class="shell"><aside class="side"><a class="brand" href="<?=BASE_URL?>thidua.php?section=student_score"><i class="bi bi-door-closed"></i><div><strong>PHÒNG NỘI TRÚ</strong><small>Thi đua học sinh</small></div></a><div class="side-title">Chức năng</div><?php if(in_array('input',$allowedTabs,true)):?><a class="nav-link <?=$tab==='input'?'active':''?>" href="?tab=input"><i class="bi bi-pencil-square"></i> Nhập liệu</a><?php endif;?><?php if(in_array('stats',$allowedTabs,true)):?><a class="nav-link <?=$tab==='stats'?'active':''?>" href="?tab=stats"><i class="bi bi-bar-chart-line"></i> Thống kê - Xếp loại</a><?php endif;?><?php if(in_array('settings',$allowedTabs,true)):?><a class="nav-link <?=$tab==='settings'?'active':''?>" href="?tab=settings"><i class="bi bi-gear"></i> Cài đặt</a><?php endif;?><a class="nav-link mt-4" href="<?=BASE_URL?>thidua.php?section=student_score"><i class="bi bi-arrow-left"></i> Nề nếp - Học tập</a></aside><main class="main"><?php show_flash();?><header class="head"><div><h2><i class="bi bi-door-closed text-warning"></i> Phòng nội trú</h2><div class="text-muted">Chấm điểm, tổng hợp và xếp loại phòng ở</div></div><span class="badge text-bg-warning p-2"><?=e($userName)?></span></header>

<?php if($tab==='input'):?>
<form class="cardx toolbar no-print" method="get"><input type="hidden" name="tab" value="input"><div><label class="form-label">Chọn ngày thuộc tuần</label><input class="form-control" type="date" name="week" value="<?=e($inputWeek['start'])?>"></div><button class="btn btn-warning"><i class="bi bi-calendar-week"></i> Tải danh sách phòng</button><div class="ms-auto"><strong>Tuần: <?=e($inputWeek['label']??($inputWeek['start'].' - '.$inputWeek['end']))?></strong><div class="small text-muted">Điểm chuẩn: <?=number_format((float)$data['settings']['weekly_max'],1,',','.')?> điểm/phòng</div></div></form>
<?php if(!$rooms):?><div class="cardx empty">Chưa có danh sách phòng. Hãy tạo hoặc đồng bộ phòng trong Quản lý nội trú → Chia phòng.</div><?php else:?><div class="room-grid"><?php foreach($rooms as $room):$saved=$inputMap[$room]??null;$savedItems=(array)($saved['items']??[]);?><section class="cardx room-card"><div class="room-head"><div><strong><?=e($room)?></strong><small class="d-block text-muted"><?=$saved?'Đã nhập '.date('d/m/Y',strtotime((string)$saved['date'])):'Chưa nhập tuần này'?></small></div><span class="badge badge-score"><?=$saved?number_format((float)$saved['score'],1,',','.').'/'.number_format((float)$saved['max_score'],1,',','.'):'—'?></span></div><div class="room-body"><form method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="entry_save"><input type="hidden" name="room" value="<?=e($room)?>"><label class="form-label">Ngày chấm</label><input class="form-control mb-3" type="date" name="date" value="<?=e($saved['date']??$inputWeek['start'])?>" required><div class="criterion-host"><?php foreach($savedItems?:[['criterion_id'=>'','quantity'=>1,'note'=>'']] as $item):?><div class="criterion-row"><select class="form-select" name="criterion[]"><option value="">Không có lỗi / Chọn mục trừ</option><?php foreach($activeCriteria as $criterion):?><option value="<?=e($criterion['id'])?>" <?=($item['criterion_id']??'')===$criterion['id']?'selected':''?>>−<?=number_format((float)$criterion['points'],1,',','.')?> · <?=e($criterion['name'])?></option><?php endforeach;?></select><input class="form-control" type="number" min="1" name="quantity[]" value="<?=max(1,(int)($item['quantity']??1))?>" title="Số lần"><input class="form-control note" name="item_note[]" value="<?=e($item['note']??'')?>" placeholder="Ghi chú"><button class="btn btn-outline-danger" type="button" onclick="this.closest('.criterion-row').remove()"><i class="bi bi-x"></i></button></div><?php endforeach;?></div><button class="btn btn-sm btn-outline-secondary mb-3" type="button" onclick="addCriterion(this)"><i class="bi bi-plus"></i> Thêm lỗi vi phạm</button><textarea class="form-control mb-3" name="general_note" rows="2" placeholder="Nhận xét chung (không bắt buộc)"><?=e($saved['general_note']??'')?></textarea><button class="btn btn-warning w-100" <?=$canEdit?'':'disabled'?>><i class="bi bi-floppy"></i> <?=$saved?'Cập nhật':'Lưu điểm phòng'?></button></form><?php if($saved&&$canDelete):?><form method="post" class="mt-2" onsubmit="return confirm('Xóa dữ liệu chấm điểm của <?=e($room)?> trong tuần này?')"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="entry_delete"><input type="hidden" name="id" value="<?=e($saved['id'])?>"><input type="hidden" name="week" value="<?=e($inputWeek['start'])?>"><button class="btn btn-sm btn-outline-danger w-100"><i class="bi bi-trash"></i> Xóa dữ liệu tuần</button></form><?php endif;?></div></section><?php endforeach;?></div><?php endif;?>

<?php elseif($tab==='stats'):?>
<form class="cardx toolbar no-print" method="get"><input type="hidden" name="tab" value="stats"><div><label class="form-label">Kiểu thống kê</label><select class="form-select" name="mode" onchange="this.form.submit()"><option value="week" <?=$statsMode==='week'?'selected':''?>>Theo tuần</option><option value="range" <?=$statsMode==='range'?'selected':''?>>Giai đoạn bất kỳ</option></select></div><?php if($statsMode==='week'):?><div><label class="form-label">Ngày thuộc tuần</label><input class="form-control" type="date" name="anchor" value="<?=e($statsAnchor)?>"></div><?php else:?><div><label class="form-label">Từ ngày</label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div><label class="form-label">Đến ngày</label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><?php endif;?><button class="btn btn-warning"><i class="bi bi-filter"></i> Xem kết quả</button><button class="btn btn-outline-secondary" type="button" onclick="window.print()"><i class="bi bi-printer"></i> In</button></form><section class="cardx p-3"><div class="d-flex justify-content-between gap-2 flex-wrap mb-3"><div><h5 class="fw-bold mb-1">Xếp loại phòng ở</h5><span class="text-muted">Từ <?=date('d/m/Y',strtotime($from))?> đến <?=date('d/m/Y',strtotime($to))?></span></div><div class="small text-muted">Xếp theo điểm trung bình giảm dần · Chỉ tính tuần đã nhập</div></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Thứ hạng</th><th>Phòng</th><th>Số tuần đã nhập</th><th>Tổng điểm trừ</th><th>Tổng điểm</th><th>Điểm trung bình</th><th>Xếp loại</th></tr></thead><tbody><?php $rank=0;foreach($summary as $row):?><tr><td><?php if($row['weeks']):$rank++;?><span class="rank <?=$rank===1?'first':''?>"><?=$rank?></span><?php else:?>—<?php endif;?></td><td><strong><?=e($row['room'])?></strong></td><td><?=e($row['weeks'])?></td><td><?=$row['weeks']?number_format($row['deduction'],1,',','.'):'—'?></td><td><?=$row['weeks']?number_format($row['total'],1,',','.'):'—'?></td><td><?=$row['weeks']?'<strong>'.number_format($row['average'],2,',','.').'</strong>':'<span class="text-muted">Chưa nhập</span>'?></td><td><?=$row['weeks']?'<span class="badge '.($row['rating']==='Tốt'?'text-bg-success':($row['rating']==='Chưa đạt'?'text-bg-danger':'text-bg-warning')).'">'.e($row['rating']).'</span>':'—'?></td></tr><?php endforeach;if(!$rooms):?><tr><td colspan="7" class="empty">Chưa có danh sách phòng.</td></tr><?php endif;?></tbody></table></div></section>

<?php else:?>
<form method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="settings_save"><section class="cardx p-3 mb-3"><h5 class="fw-bold">Quy định điểm và xếp loại</h5><div class="row g-3"><div class="col-md-3"><label class="form-label">Tổng điểm một phòng/tuần</label><input class="form-control" type="number" min="1" step=".1" name="weekly_max" value="<?=e($data['settings']['weekly_max'])?>" required></div><div class="col-md-3"><label class="form-label">Tốt từ (%)</label><input class="form-control" type="number" min="0" max="100" step=".1" name="excellent" value="<?=e($data['settings']['excellent'])?>"></div><div class="col-md-3"><label class="form-label">Khá từ (%)</label><input class="form-control" type="number" min="0" max="100" step=".1" name="good" value="<?=e($data['settings']['good'])?>"></div><div class="col-md-3"><label class="form-label">Đạt từ (%)</label><input class="form-control" type="number" min="0" max="100" step=".1" name="pass" value="<?=e($data['settings']['pass'])?>"></div></div><div class="form-text mt-2">Mặc định: Tốt ≥90%, Khá ≥80%, Đạt ≥65%, dưới 65% là Chưa đạt. Có thể thay đổi tại đây.</div></section><section class="cardx p-3"><div class="d-flex justify-content-between align-items-center mb-3"><div><h5 class="fw-bold mb-1">Các mục điểm trừ</h5><span class="text-muted small">Chỉ các mục chọn “Hiển thị” mới xuất hiện trong danh sách xổ xuống ở tab Nhập liệu.</span></div><button class="btn btn-outline-warning" type="button" onclick="addSettingRow()"><i class="bi bi-plus"></i> Thêm mục</button></div><div id="settingRows"><?php foreach($data['criteria'] as $criterion):?><div class="setting-row"><input class="form-control criterion-id" name="criterion_id[]" value="<?=e($criterion['id'])?>" readonly><input class="form-control" name="criterion_name[]" value="<?=e($criterion['name'])?>" placeholder="Nội dung vi phạm" required><input class="form-control" type="number" min=".01" step=".01" name="criterion_points[]" value="<?=e($criterion['points'])?>" title="Điểm trừ" required><select class="form-select" name="criterion_active[]"><option value="1" <?=!empty($criterion['active'])?'selected':''?>>Hiển thị</option><option value="0" <?=empty($criterion['active'])?'selected':''?>>Ẩn</option></select><button class="btn btn-outline-danger" type="button" onclick="this.closest('.setting-row').remove()"><i class="bi bi-trash"></i></button></div><?php endforeach;?></div><div class="text-end mt-3"><button class="btn btn-warning px-4" <?=$canEdit?'':'disabled'?>><i class="bi bi-floppy"></i> Lưu cài đặt</button></div></section></form>
<?php endif;?></main></div><template id="criterionTemplate"><div class="criterion-row"><select class="form-select" name="criterion[]"><option value="">Không có lỗi / Chọn mục trừ</option><?php foreach($activeCriteria as $criterion):?><option value="<?=e($criterion['id'])?>">−<?=number_format((float)$criterion['points'],1,',','.')?> · <?=e($criterion['name'])?></option><?php endforeach;?></select><input class="form-control" type="number" min="1" name="quantity[]" value="1" title="Số lần"><input class="form-control note" name="item_note[]" placeholder="Ghi chú"><button class="btn btn-outline-danger" type="button" onclick="this.closest('.criterion-row').remove()"><i class="bi bi-x"></i></button></div></template><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>
function addCriterion(button){var host=button.closest('form').querySelector('.criterion-host'),template=document.getElementById('criterionTemplate');host.appendChild(template.content.cloneNode(true))}
function addSettingRow(){var host=document.getElementById('settingRows'),row=document.createElement('div');row.className='setting-row';row.innerHTML='<input class="form-control criterion-id" name="criterion_id[]" readonly placeholder="Tự tạo"><input class="form-control" name="criterion_name[]" placeholder="Nội dung vi phạm" required><input class="form-control" type="number" min=".01" step=".01" name="criterion_points[]" value="1" required><select class="form-select" name="criterion_active[]"><option value="1">Hiển thị</option><option value="0">Ẩn</option></select><button class="btn btn-outline-danger" type="button" onclick="this.closest(\'.setting-row\').remove()"><i class="bi bi-trash"></i></button>';host.appendChild(row)}
</script></body></html>
